import React from "react";
import { Link } from "react-router-dom";

function NavBar() {
  const planets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <div className=" bg-gray-900  text-white justify-center">
      <ul className=" md: ">
        <li>
          <Link to="/">Home</Link>
        </li>
        <li>
          <select name="" id="" className="bg-transparent drop">
            {planets.map((p) => {
              return <option value={p}><Link>{p}</Link></option>;
            })}
          </select>
        </li>
      </ul>
    </div>
  );
}

export default NavBar;
